pattern:
awk '
NR<=51 {print; next}
NR==59 || NR==60 {h = h $0 "\n"; next}
NR>=52 && NR<=56 {k = k $0 "\n"; next}
NR==57 || NR==58 {next}
{ if (k != "") { printf "%s%s", h, k; h=""; k="" } print }
END { if (k != "") printf "%s%s", h, k }
' TASKS.md mv TASKS.new TASKS.md python3 tools/md-table-check/check.py TASKS.md tail -1 sed -n '50,63p' TASKS.md cut -c1-60
